// Немає тестового фреймворку в проєкті (package.json) — простий assert-
// скрипт, той самий принцип, що word-training-session.test.ts.
// Запуск вручну: npx tsx src/lib/exercises/task-display-name.test.ts
import { taskDisplayName, isAutoGeneratedTaskTitle } from "./task-display-name";

let failures = 0;
function assert(condition: boolean, label: string) {
  if (!condition) {
    failures++;
    console.error(`FAIL: ${label}`);
  }
}

// --- isAutoGeneratedTaskTitle ------------------------------------------

// Повна форма "<префікс>: <слова>…" (основний випадок зі звіту помилки).
assert(
  isAutoGeneratedTaskTitle("Переставити літери: signer, formulaire, autant…") === true,
  "full prefix + preview + ellipsis is auto-generated"
);
assert(
  isAutoGeneratedTaskTitle("З'єднайте елементи: signer, un formulaire, se co…") === true,
  "matching auto title is auto-generated"
);
// Короткий прев'ю без еліпсису (влазить у 60 символів без обрізання) —
// усе ще впізнається через префіксний збіг, не лише через "…".
assert(
  isAutoGeneratedTaskTitle("Заповніть пропуск: Bonjour") === true,
  "short preview without ellipsis still matches via prefix"
);
// Гола назва типу без хвоста (generateTaskTitle fallback, коли конфіг без
// прев'ю-елементів).
assert(isAutoGeneratedTaskTitle("Філворд") === true, "bare type label with no tail is auto-generated");
assert(isAutoGeneratedTaskTitle("Вибір зайвого") === true, "word_choice cross_out variant label is auto-generated");

// Ручні назви (вчителька написала сама) — НЕ автогенеровані.
assert(isAutoGeneratedTaskTitle("1") === false, "manual short title '1' is not auto-generated");
assert(isAutoGeneratedTaskTitle("HP") === false, "manual short title 'HP' is not auto-generated");
assert(isAutoGeneratedTaskTitle("Act 1") === false, "manual title 'Act 1' is not auto-generated");
assert(isAutoGeneratedTaskTitle("Cas particuliers") === false, "manual French title is not auto-generated");
assert(isAutoGeneratedTaskTitle("") === false, "empty string is not auto-generated");

// Запасна евристика (невідомий префікс, але той самий силует "...: ...…").
assert(
  isAutoGeneratedTaskTitle("Якийсь новий тип: слово1, слово2…") === true,
  "unknown prefix but ellipsis-after-colon shape still matches the fallback heuristic"
);
// Колонка є, але БЕЗ еліпсису і БЕЗ відомого префікса — не автоназва
// (замало сигналів: може бути ручний підзаголовок "Увага: перевірте форму").
assert(
  isAutoGeneratedTaskTitle("Увага: перевірте форму дієслова") === false,
  "colon without a known prefix or trailing ellipsis is treated as manual"
);

// --- taskDisplayName ----------------------------------------------------

assert(
  taskDisplayName("letter_rearrangement", "Переставити літери: signer, formulaire, autant…") === "Lettres en désordre",
  "auto-generated title falls back to the French type name"
);
assert(
  taskDisplayName("matching", "З'єднайте елементи: signer, un formulaire, se co…") === "Association",
  "matching auto title falls back to its French type name"
);
assert(
  taskDisplayName("table_fill", "Заповніть таблицю: signer, un formulaire…") === "Tableau à compléter",
  "table_fill auto title falls back to its French type name"
);
assert(
  taskDisplayName("image_match", "Перетягніть назви під картинки: brebis, coq, ch…") === "Images et mots",
  "image_match auto title falls back to its French type name"
);
assert(taskDisplayName("multiple_choice", "HP") === "HP", "manual title is preserved as-is");
assert(taskDisplayName("multiple_choice", "Cas particuliers") === "Cas particuliers", "manual French title is preserved");
assert(taskDisplayName("multiple_choice", null) === "Choix multiple", "null title falls back to the type name");
assert(taskDisplayName("multiple_choice", "") === "Choix multiple", "empty title falls back to the type name");
assert(taskDisplayName("multiple_choice", "   ") === "Choix multiple", "whitespace-only title falls back to the type name");

// Ординал.
assert(taskDisplayName("multiple_choice", null, 2) === "Choix multiple · 2", "ordinal is appended when given");
assert(taskDisplayName("multiple_choice", "HP", 3) === "HP · 3", "ordinal is appended even to a manual title");
assert(taskDisplayName("multiple_choice", null, null) === "Choix multiple", "null ordinal adds no suffix");
assert(taskDisplayName("multiple_choice", null, 0) === "Choix multiple", "zero ordinal adds no suffix (unique in list)");
assert(taskDisplayName("multiple_choice", null, undefined) === "Choix multiple", "omitted ordinal adds no suffix");

if (failures > 0) {
  console.error(`\n${failures} test(s) failed.`);
  process.exit(1);
} else {
  console.log("All task-display-name tests passed.");
}
